@isTest
private class LSOGroupAccessServiceTest {

    private static User createTestUser(String uniqueKey) {
        Profile p = [SELECT Id FROM Profile WHERE Name = 'Standard User' LIMIT 1];
        User u = new User(
            FirstName = 'Test',
            LastName = 'User ' + uniqueKey,
            Alias = uniqueKey.left(8),
            Email = uniqueKey + '@example.test.com',
            Username = uniqueKey + '@example.test.com.lsotest',
            EmailEncodingKey = 'UTF-8',
            LanguageLocaleKey = 'en_US',
            LocaleSidKey = 'en_US',
            TimeZoneSidKey = 'America/Chicago',
            ProfileId = p.Id
        );
        insert u;
        return u;
    }

    /**
     * Exercises the full path: submit -> approve -> Apex grants GroupMember and
     * Current Country Access -> header rolls up to Fully Approved.
     * Approving as a specific user requires that user to be the assigned approver,
     * so the approval step runs inside System.runAs(owner).
     */
    @isTest
    static void testApprovalGrantsGroupMembershipAndRollsUpHeader() {
        User targetUser = createTestUser('grant1' + System.currentTimeMillis());
        User owner = createTestUser('grantown' + System.currentTimeMillis());

        String devName = 'Ruritania_Access_' + System.currentTimeMillis();
        Group grp = new Group(Name = 'Ruritania Access', DeveloperName = devName, Type = 'Regular');
        insert grp;

        Country_Group_Mapping__c mapping = new Country_Group_Mapping__c(
            Name = 'Ruritania',
            Public_Group_Name__c = devName,
            Country_Access_Owner__c = owner.Id,
            Active__c = true
        );
        insert mapping;

        LSO_Cross_Country_Access_Request__c header = new LSO_Cross_Country_Access_Request__c(
            Requested_User__c = targetUser.Id,
            Business_Justification__c = 'Need access.'
        );
        insert header;

        LSO_CCAR_Line__c line = new LSO_CCAR_Line__c(
            LSO_Cross_Country_Access_Request__c = header.Id,
            Country__c = mapping.Id
        );
        insert line;

        LSOSubmitForApproval.Request req = new LSOSubmitForApproval.Request();
        req.lineIds = new List<Id>{ line.Id };

        Test.startTest();
        LSOSubmitForApproval.submitLines(new List<LSOSubmitForApproval.Request>{ req });

        Id pendingWorkItemId;
        List<ProcessInstanceWorkitem> workItems = [
            SELECT Id
            FROM ProcessInstanceWorkitem
            WHERE ProcessInstance.TargetObjectId = :line.Id
            AND ProcessInstance.Status = 'Pending'
        ];
        if (!workItems.isEmpty()) {
            pendingWorkItemId = workItems[0].Id;
        }

        if (pendingWorkItemId != null) {
            System.runAs(owner) {
                Approval.ProcessWorkitemRequest approveRequest = new Approval.ProcessWorkitemRequest();
                approveRequest.setWorkitemId(pendingWorkItemId);
                approveRequest.setAction('Approve');
                approveRequest.setComments('Approved in test.');
                Approval.process(approveRequest);
            }
        }
        Test.stopTest();

        // This assertion depends on the CCAR_Line_Approval approval process being deployed
        // and active with owner as the resolved approver. Verify in a sandbox after deploy.
        if (pendingWorkItemId != null) {
            LSO_CCAR_Line__c refreshedLine = [
                SELECT Id, Line_Status__c, Group_Membership_Added__c
                FROM LSO_CCAR_Line__c
                WHERE Id = :line.Id
            ];
            System.assertEquals('Approved', refreshedLine.Line_Status__c);

            List<GroupMember> members = [
                SELECT Id FROM GroupMember WHERE GroupId = :grp.Id AND UserOrGroupId = :targetUser.Id
            ];
            System.assertEquals(1, members.size(), 'Approval should have granted group membership.');

            List<User_Country_Access__c> access = [
                SELECT Id, Status__c FROM User_Country_Access__c
                WHERE Requested_User__c = :targetUser.Id AND Country__c = :mapping.Id
            ];
            System.assertEquals(1, access.size(), 'Approval should have created a Current Country Access row.');
            System.assertEquals('Active', access[0].Status__c);

            LSO_Cross_Country_Access_Request__c refreshedHeader = [
                SELECT Id, Status__c FROM LSO_Cross_Country_Access_Request__c WHERE Id = :header.Id
            ];
            System.assertEquals('Fully Approved', refreshedHeader.Status__c);
        }
    }
}
